    gender_f: 'Girl', gender_m: 'Boy',
    setDayNightOn: 'Day & night: ON', setDayNightOff: 'Day & night: OFF', swAnim: 'Animations', swDayNight: 'Day & night', swBirds: 'Birds', swNoFly: 'Remove flying objects', swBirdsLate: 'Birds in later eras', swClouds: 'Clouds', swSteam: 'Manhole steam', swRain: 'Rain', swBig: 'Large text', swVib: 'Vibration', setBirdsOn: 'Birds: ON', setBirdsOff: 'Birds: OFF', setCloudsOn: 'Clouds: ON', setCloudsOff: 'Clouds: OFF', setSteamOn: 'Manhole steam: ON', setSteamOff: 'Manhole steam: OFF', setBigOn: 'Large text: ON', setBigOff: 'Large text: OFF', setVibOn: 'Vibration: ON', setVibOff: 'Vibration: OFF', setEvents0: 'Events: normal', setEvents1: 'Events: rarer', setEvents2: 'Events: minimal', setEventsNote: 'Events are the circus, era animals, ghosts, sales and mishaps. “Rarer” is 2.5 times less often, “minimal” is 5 times.',
    panHint: "Swipe left or right to see the whole street.",
    team_spike_say_3: "I'll give your change in pennies. All of them. Count.", team_spike_say_4: "Don't touch the spines. Touch the register, preferably with cash.", team_spike_say_5: "A receipt? Only with my signature and a reproach.",
    team_bodya_say_3: "Solid house, solid nerves. I rent out the nerves.", team_bodya_say_4: "Half a plank, half the job. We'll see the rest on Monday.", team_bodya_say_5: "Whoever built a dam can handle a mall. It's only a question of price.",
    team_zoya_say_3: "Buy two, get the third free. I've already priced it in, don't worry.", team_zoya_say_4: "Today only. Yes, I say that every day.", team_zoya_say_5: "My favorite sport is jumping on discounts. And on people's nerves.",
    team_tonya_say_3: "Slow and steady wins. No guarantees either.", team_tonya_say_4: "I see everything. Even with my eyes closed. Especially then.", team_tonya_say_5: "The shell is tough, the nerves are tougher. Salary: we'll see.",
    team_mikhas_say_3: "I lift the load and still smile. The smile costs extra.", team_mikhas_say_4: "Who said it's heavy? I'm fine. My back isn't.", team_mikhas_say_5: "After this crate, a break. Preferably a long one.",
    team_sonia_say_3: "Debit and credit get along. Though I've seen them fight.", team_sonia_say_4: "I count at night when everyone's asleep. Cheaper for the nerves.", team_sonia_say_5: "A penny saved is a penny earned, and an owl saves you from audits.",
    team_kria_say_3: "There was a puddle here. Now there isn't. Case closed.", team_kria_say_4: "It's clean where I am. Where I haven't been, they just haven't noticed yet.", team_kria_say_5: "Sweep with the tail, wipe with the feet. No offense.",
    team_zhuzha_say_3: "Green is the new black. Just trust me.", team_zhuzha_say_4: "I leap after trends faster than anyone. Sometimes ahead of them.", team_zhuzha_say_5: "Everything truly stylish croaks a little.",
    team_leo_say_3: "Let's sync up. And then once more, just in case.", team_leo_say_4: "I have a plan. And a plan in case the plan fails.", team_leo_say_5: "Cunning is just efficiency that put on a tie in time.",
    team_pao_say_3: "Bamboo and discounts bring people together. So do scandals.", team_pao_say_4: "We don't sell things. We sell expectations. Other people's.", team_pao_say_5: "Who said advertising doesn't eat bamboo? Mine does.",
    team_murzyk_say_3: "Charging in the sun. Energy-efficient and suspiciously pleasant.", team_murzyk_say_4: "Mice? No, I only fix computer ones. I pity the others.", team_murzyk_say_5: "Cables are so tasty... I mean tangled.",
    team_toma_say_3: "My trunk won't fail: everything's in place. Except what somebody moved.", team_toma_say_4: "I remember where every screw is. And who took it.", team_toma_say_5: "A warehouse is like an elephant: big, calm, and best not annoyed.",
    capy_say_3: "Welcome to my shop. Prices are human, illusions are free.", capy_say_4: "The flower on my head brings luck. Otherwise, why have it.", capy_say_5: "Capybaras are the calmest traders in the world. Calm is expensive.",
    setEpochView: 'Epoch viewer', setEpochViewNote: 'Pick one of the epochs you have passed: the look, goods and music change. Under each name: the current epoch shows your balance, as in the counter; passed epochs show what was earned in them. New coins, including offline ones, count in the selected epoch. New epochs unlock with time travel.', epochViewing: 'Epoch: {0}', epochBalance: 'Balance: {0}',
    setSeason: 'Season', setSeasonNote: 'Changes the trees, weather and mood of the street. "Auto" uses the date on your device.',
